def transform(grid):
    """Copy the non-background-colored pixel mask onto matching all-zero positions."""
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v not in (0, 8)}
    if not colors:
        return [row[:] for row in grid]
    color = next(iter(colors))
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    shape = {(r-r0, c-c0) for r, c in pts}
    out = [row[:] for row in grid]
    for r in range(h-(r1-r0+1)+1):
        for c in range(w-(c1-c0+1)+1):
            if all(grid[r+dr][c+dc] == 0 for dr, dc in shape):
                for dr, dc in shape:
                    out[r+dr][c+dc] = color
    return out

